2	pragma solidity ^0.8.24;
3	
4	import {Test} from "forge-std/Test.sol";
5	import {Auction} from "../src/Auction.sol";
6	import {ZPunks} from "../src/impls/RealNFT.sol";
7	import {ERC20Mock} from "@openzeppelin/contracts/mocks/token/ERC20Mock.sol";
8	import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
9	import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
10	import {SymTest} from "halmos-cheatcodes/SymTest.sol";
11	
12	contract SystemInvariantTest is Test, SymTest {
13	    Auction public auction;
14	    ZPunks public nft;
15	    ERC20Mock public token;
16	
17	    // --- GHOST STATE ---
18	    uint256 public ghost_bidSum;
19	    address public ghost_max_bidder;
20	    uint256 public ghost_nbid;
21	    address public ghost_winner;
22	    bool public ghost_has_finished;
23	    uint256 public ghost_n_iterations;
24	
25	    address[] public bidders;
26	    address public owner;
27	
28	    mapping(address => uint256) public ghost_bids;
29	
30	    // --- STRUTTURE PER IL FUZZING BOUNDED ---
31	    enum ActionType {
32	        BID,
33	        FINISH,
34	        NOOP
35	    }
36	
37	    struct Action {
38	        uint8 actionType;
39	        uint256 amount;
40	        uint256 bidderSeed;
41	    }
42	
43	    struct ActionHalmos {
44	        uint8 actionType;
45	        uint256 amount;
46	        uint8 bidderIndex;
47	    }
48	
49	    // Spostato da constructor a setUp per totale compatibilità con Halmos
50	    function setUp() public {
51	        token = new ERC20Mock();
52	        ghost_nbid = 0;
53	        ghost_n_iterations = 0;
54	        ghost_has_finished = false;
55	
56	        // Ridotto a 3 bidder per evitare lo State Explosion su Halmos,
57	        // mantenendo comunque la competizione tra utenti.
58	        for (uint256 i = 0; i < 3; i++) {
59	            address bidder = makeAddr(string(abi.encodePacked("bidder", i)));
60	            bidders.push(bidder);
61	            token.mint(bidder, 100_000);
62	        }
63	
64	        owner = makeAddr("owner");
65	        nft = new ZPunks(owner);
66	
67	        instantiate_auction();
68	    }
69	
70	    function instantiate_auction() internal {
71	        vm.startPrank(owner);
72	        nft.safeMint(owner, "");
73	
74	        // Passiamo ghost_n_iterations come tokenId corrente
75	        auction = new Auction(
76	            IERC20(address(token)),
77	            IERC721(address(nft)),
78	            ghost_n_iterations,
79	            owner,
80	            block.timestamp,
81	            block.timestamp + 7 days
82	        );
83	
84	        nft.approve(address(auction), ghost_n_iterations);
85	        vm.stopPrank();
86	    }
87	
88	    // --- ENTRYPOINT OTTIMIZZATO PER HALMOS ---
89	    function check_SystemInvariants(ActionHalmos[3] memory actions) public {
90	        // 1. Vincoliamo i tipi di azione e gli indici dei bidder
91	        vm.assume(actions[0].actionType <= 2 && actions[0].bidderIndex <= 2);
92	        vm.assume(actions[1].actionType <= 2 && actions[1].bidderIndex <= 2);
93	        vm.assume(actions[2].actionType <= 2 && actions[2].bidderIndex <= 2);
94	
95	        // 2. Vincoliamo gli importi dei BID direttamente qui per evitare il cheatcode 'bound'
96	        vm.assume(actions[0].amount >= 1 && actions[0].amount <= 100_000);
97	        vm.assume(actions[1].amount >= 1 && actions[1].amount <= 100_000);
98	        vm.assume(actions[2].amount >= 1 && actions[2].amount <= 100_000);
99	
100	        for (uint256 i = 0; i < actions.length; i++) {
101	            ActionHalmos memory action = actions[i];
102	            ActionType act = ActionType(action.actionType);
103	            address currentBidder = bidders[action.bidderIndex];
104	
105	            if (act == ActionType.BID) {
106	                // Rimuovi il bound interno a _executeBid se usi i vm.assume sopra
107	                _executeBid(currentBidder, action.amount);
108	            } else if (act == ActionType.FINISH) {
109	                _executeFinish(currentBidder);
110	            }
111	
112	            _assertInvariants();
113	        }
114	        _executeFinish(owner);
115	    }
116	
117	    // Definiamo una sequenza di 4 azioni consecutive nello stesso stato
118	    // --- ENTRYPOINT UNICO PER FOUNDRY---
119	    function test_SystemInvariants(Action[4] memory actions) public {
120	        actions[0].actionType = uint8(bound(actions[0].actionType, 0, 2));
121	        actions[1].actionType = uint8(bound(actions[0].actionType, 0, 2));
122	        actions[2].actionType = uint8(bound(actions[0].actionType, 0, 2));
123	        actions[3].actionType = uint8(bound(actions[0].actionType, 0, 2));
124	
125	        for (uint256 i = 0; i < actions.length; i++) {
126	            Action memory action = actions[i];
127	            ActionType act = ActionType(action.actionType);
128	
129	            // Selezione deterministica/simbolica del bidder dall'array
130	            uint256 bidderIndex = action.bidderSeed % bidders.length;
131	            address currentBidder = bidders[bidderIndex];
132	
133	            if (act == ActionType.BID) {
134	                uint256 boundedAmount = bound(action.amount, 1, 100_000);
135	                _test_executeBid(currentBidder, boundedAmount);
136	            } else if (act == ActionType.FINISH) {
137	                _test_executeFinish(currentBidder);
138	            }
139	            // Se ActionType.NOOP non fa nulla (permette sequenze più corte)
140	
141	            // Controlla le invarianti alla fine di OGNI transazione della sequenza
142	            _assertInvariants();
143	        }
144	        _test_executeFinish(owner);
145	        instantiate_auction();
146	    }
147	
148	    // --- LOGICA DI ESECUZIONE DELLE AZIONI ---
149	
150	    function _executeBid(address bidder, uint256 amount) internal {
151	        vm.startPrank(bidder);
152	        // Approviamo l'asta a prelevare i token ERC20 del bidder
153	        token.approve(address(auction), amount);
154	
155	        // Il try/catch assicura che aggiorniamo lo stato ghost SOLO se l'asta accetta il bid
156	        if (ghost_has_finished) {
157	            vm.stopPrank();
158	            return;
159	        }
160	        auction.bid(amount);
161	        ghost_nbid += 1;
162	        ghost_bids[bidder] += amount;
163	        ghost_bidSum += amount;
164	
165	        if (ghost_max_bidder == address(0) || ghost_bids[bidder] > ghost_bids[ghost_max_bidder]) {
166	            ghost_max_bidder = bidder;
167	        }
168	
169	        vm.stopPrank();
170	    }
171	
172	    function _executeFinish(address caller) internal {
173	        // entro la sequenza limitata a 4 step totali.
174	
175	        // Saltiamo oltre i 7 giorni per far scadere l'asta
176	        vm.warp(block.timestamp + 7 days + 1);
177	
178	        vm.startPrank(caller);
179	        if (ghost_has_finished) {
180	            vm.stopPrank();
181	            return;
182	        }
183	
184	        address winner = auction.finishAuction();
185	        ghost_winner = winner;
186	        ghost_has_finished = true;
187	
188	        // Per testare la "prossima iterazione", incrementiamo il contatore
189	        // e prepariamo la nuova asta nello stesso slot di esecuzione
190	        ghost_n_iterations += 1;
191	        // instantiate_auction();
192	
193	        vm.stopPrank();
194	    }
195	
196	    function _test_executeBid(address bidder, uint256 amount) internal {
197	        // Evitiamo bid superiori al bilancio o pari a zero per non sporcare i path puliti
198	        amount = bound(amount, 1, 100_000);
199	
200	        vm.startPrank(bidder);
201	        // Approviamo l'asta a prelevare i token ERC20 del bidder
202	        token.approve(address(auction), amount);
203	
204	        // Il try/catch assicura che aggiorniamo lo stato ghost SOLO se l'asta accetta il bid
205	        if (ghost_has_finished) {
206	            vm.expectRevert(Auction.AlreadyFinished.selector);
207	            auction.bid(amount);
208	            vm.stopPrank();
209	            return;
210	        }
211	        auction.bid(amount);
212	        ghost_nbid += 1;
213	        ghost_bids[bidder] += amount;
214	        ghost_bidSum += amount;
215	
216	        if (ghost_max_bidder == address(0) || ghost_bids[bidder] > ghost_bids[ghost_max_bidder]) {
217	            ghost_max_bidder = bidder;
218	        }
219	
220	        vm.stopPrank();
221	    }
222	
223	    function _test_executeFinish(address caller) internal {
224	        // entro la sequenza limitata a 4 step totali.
225	
226	        // Saltiamo oltre i 7 giorni per far scadere l'asta
227	        vm.warp(block.timestamp + 7 days + 1);
228	
229	        vm.startPrank(caller);
230	        if (ghost_has_finished) {
231	            vm.expectRevert(Auction.AlreadyFinished.selector);
232	            auction.finishAuction();
233	            vm.stopPrank();
234	            return;
235	        }
236	
237	        address winner = auction.finishAuction();
238	        ghost_winner = winner;
239	        ghost_has_finished = true;
240	
241	        // Per testare la "prossima iterazione", incrementiamo il contatore
242	        // e prepariamo la nuova asta nello stesso slot di esecuzione
243	        ghost_n_iterations += 1;
244	        // instantiate_auction();
245	
246	        vm.stopPrank();
247	    }
248	
249	    // --- LE TUE INVARIANTI COMPILATE ---
250	    function _assertInvariants() internal view {
251	        // Ripristinato il tuo test sui bid mappati
252	        // Se l'asta è stata conclusa con successo, verifica il vincitore e l'NFT
253	        if (ghost_has_finished && ghost_nbid > 0) {
254	            assert(ghost_winner != address(0));
255	            assert(ghost_max_bidder == ghost_winner);
256	
257	            // Verifica che il vincitore abbia ricevuto l'NFT dell'iterazione precedente (quella conclusa)
258	            uint256 completedAuctionId = ghost_n_iterations - 1;
259	            assert(ghost_winner == nft.ownerOf(completedAuctionId));
260	        }
261	    }
262	}
